def sort_list(head); length = 0; node = head; while node; length += 1; node = node.next; end; dummy = ListNode.new(0); dummy.next = head; width = 1; while width < length; tail = dummy; current = dummy.next; while current; left = current; right = split_run(left, width); current = split_run(right, width); while left && right; if left.val <= right.val; tail.next = left; left = left.next; else; tail.next = right; right = right.next; end; tail = tail.next; end; tail.next = left || right; tail = tail.next while tail.next; end; width *= 2; end; dummy.next; end; def split_run(head, size); return nil unless head; index = 1; while index < size && head.next; head = head.next; index += 1; end; rest = head.next; head.next = nil; rest; end
